#![allow(dead_code)]
//! Tool marks, as terminal cells. GENERATED by scripts/logos.py -- do
//! not edit. Each cell is a glyph plus the coverage of the mark's own
//! colour in front and behind it, so a mark can be dimmed or lit
//! without being regenerated.

/// glyph, foreground coverage, background coverage
pub type Cell = (char, u8, u8);

pub struct Art {
    pub cols: u16,
    pub rows: u16,
    pub cells: &'static [Cell],
}

pub struct Logo {
    pub id: &'static str,
    pub name: &'static str,
    pub rgb: (u8, u8, u8),
    pub lg: Art,
    pub sm: Art,
}

impl Logo {
    pub fn art(&self, small: bool) -> &Art {
        if small { &self.sm } else { &self.lg }
    }
}

pub fn find(id: &str) -> Option<&'static Logo> {
    LOGOS.iter().find(|l| l.id == id)
}

