/// Every mark, laid out as a contact sheet. A development aid: these are
/// generated by a script that cannot see a terminal, so this is how you find
/// out whether one of them came out as mush.
pub fn sheet() -> String {
    const BG: (u8, u8, u8) = (6, 7, 10);
    let blend = |c: (u8, u8, u8), a: u8| {
        let a = a as f32 / 255.0;
        (
            (BG.0 as f32 + (c.0 as f32 - BG.0 as f32) * a) as u8,
            (BG.1 as f32 + (c.1 as f32 - BG.1 as f32) * a) as u8,
            (BG.2 as f32 + (c.2 as f32 - BG.2 as f32) * a) as u8,
        )
    };
    let mut out = String::new();
    for row in LOGOS.chunks(6) {
        for r in 0..row[0].lg.rows as usize {
            for l in row {
                let a = &l.lg;
                for c in 0..a.cols as usize {
                    let (ch, f, b) = a.cells[r * a.cols as usize + c];
                    if f == 0 && b == 0 {
                        out.push_str("\x1b[0m ");
                        continue;
                    }
                    let (fr, fg, fb) = blend(l.rgb, f);
                    let (br, bg, bb) = blend(l.rgb, b);
                    out.push_str(&format!(
                        "\x1b[38;2;{fr};{fg};{fb}m\x1b[48;2;{br};{bg};{bb}m{ch}"
                    ));
                }
                out.push_str("\x1b[0m  ");
            }
            out.push('\n');
        }
        for l in row {
            let n: String = l.name.chars().take(16).collect();
            let pad = (16 - n.chars().count()) / 2;
            out.push_str(&format!(
                "\x1b[38;2;150;155;165m{}{}\x1b[0m{}  ",
                " ".repeat(pad),
                n,
                " ".repeat(16 - pad - n.chars().count())
            ));
        }
        out.push_str("\n\n");
    }
    out
}
